#!/bin/sh
set -eu
python3 - <<'AGENTDNS_PY'
import base64,hashlib,json,pathlib,subprocess
root=pathlib.Path('/opt/agentdns-secondary');path=root/'observe_native_bind.py';previous=path.read_bytes()
assert hashlib.sha256(previous).hexdigest()=='ed3356bf84446da95aac728481797f31fecd755b9ac427e2c5ea3f009ab25daa'
backup=root/'observe_native_bind-smoke.py'
with backup.open('xb') as f:f.write(previous)
backup.chmod(0o600)
raw=base64.b64decode('');assert hashlib.sha256(raw).hexdigest()=='6bb1803905af34968bd3c5cd489ba2275dda1ac575649bc5dc15790037fa461e'
path.write_bytes(raw);path.chmod(0o600)
writer="import pathlib,sys,hashlib; p=pathlib.Path('/tmp/observe_native_bind.py'); raw=sys.stdin.buffer.read(20000); assert len(raw)<20000; p.write_bytes(raw); p.chmod(0o600); print(hashlib.sha256(p.read_bytes()).hexdigest())"
r=subprocess.run(['docker','exec','-i','agentdns-secondary','python3','-c',writer],input=raw,capture_output=True,check=True,timeout=15)
actual=r.stdout.decode().strip();assert actual=='6bb1803905af34968bd3c5cd489ba2275dda1ac575649bc5dc15790037fa461e'
print(json.dumps({'previous_smoke_source_sha256':'ed3356bf84446da95aac728481797f31fecd755b9ac427e2c5ea3f009ab25daa','long_collector_source_sha256':actual,'requested_long_seconds':1380,'expected_samples':139,'collector_started':False,'scope':'one-line duration bound increase plus error message; no new physicalsmoke claimed'}))
AGENTDNS_PY
